import { PropsWithChildren } from "react";

type Props = PropsWithChildren<{
  bg?: string;
  fg?: string;
}>;

export default function Pill({ children, bg = "bg-background-darken", fg = "text-foreground" }: Props) {

  const className = `rounded-full px-4 py-2 text-sm font-medium select-none ${bg} ${fg}`;

  return (
    <div className={className}>
      {children}
    </div>
  );
}